// Builds one email per group (sale order + company, or a single non-sale request).
// Groups without an active ADMIN in that company are skipped (never sent to anyone else);
// they stay unnotified and expire at 23:59 CDMX like any other pending request.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const PANEL_URL = 'https://agroerp.hosting3m.com/admin/autorizaciones';

const out = [];
for (const item of $input.all()) {
  const d = item.json;
  if (!d.admin_emails) continue;

  const animales = typeof d.animales === 'string' ? JSON.parse(d.animales) : (d.animales || []);
  const isSale = d.tipo_evento === 'VENTA';
  const tipoLegible = isSale ? 'Baja por Venta' : 'Baja por Mortandad';
  const total = Number(d.total) || animales.length;

  // Summary per transit guide
  const porGuia = {};
  for (const a of animales) {
    const key = a.guia_transito || 'Sin guía';
    porGuia[key] = porGuia[key] || {};
    const cat = a.category || 'N/D';
    porGuia[key][cat] = (porGuia[key][cat] || 0) + 1;
  }
  const resumenGuias = Object.entries(porGuia).map(([guia, cats]) => {
    const n = Object.values(cats).reduce((s, x) => s + x, 0);
    const detalle = Object.entries(cats).map(([c, x]) => `${x} ${esc(c)}`).join(', ');
    return `<li><strong>Guía ${esc(guia)}:</strong> ${n} animal(es) — ${detalle}</li>`;
  }).join('');

  const filas = animales.map((a, i) => `
      <tr>
        <td style="padding:4px 8px;border:1px solid #ddd;">${i + 1}</td>
        <td style="padding:4px 8px;border:1px solid #ddd;">${esc(a.rfid_siniiga || a.electronic_rfid || '—')}</td>
        <td style="padding:4px 8px;border:1px solid #ddd;">${esc(a.numero_fuego || '—')}</td>
        <td style="padding:4px 8px;border:1px solid #ddd;">${esc(a.category || '—')}</td>
        <td style="padding:4px 8px;border:1px solid #ddd;">${esc(a.guia_transito || '—')}</td>
      </tr>`).join('');

  let detalleMortandad = '';
  if (d.tipo_evento === 'BAJA_MORTANDAD' && animales[0]) {
    const a = animales[0];
    detalleMortandad = `
      <li><strong>Causa:</strong> ${esc(a.causa_mortandad || 'N/A')}</li>
      <li><strong>Fecha del evento:</strong> ${esc(a.fecha_evento || 'N/A')}</li>
      <li><strong>Descripción:</strong> ${esc(a.descripcion || 'Sin descripción')}</li>`;
  }

  const fechaEvento = animales.find((a) => a.fecha_evento)?.fecha_evento;
  const titulo = d.order_code ? `Orden de venta ${esc(d.order_code)}` : tipoLegible;

  const html = `
    <h2>🐄 ${titulo} — ${esc(d.company_name)}</h2>
    <p><strong>Tipo:</strong> ${esc(tipoLegible)} · <strong>Animales de esta empresa:</strong> ${total}</p>
    <ul>
      <li><strong>Solicitado por:</strong> ${esc(d.solicitado_por)}</li>
      <li><strong>Fecha de solicitud:</strong> ${esc(d.fecha_solicitud_cdmx)} (hora CDMX)</li>
      ${fechaEvento ? `<li><strong>Fecha del evento:</strong> ${esc(fechaEvento)}</li>` : ''}
      ${detalleMortandad}
    </ul>
    ${isSale ? `<p><strong>Resumen por guía de tránsito:</strong></p><ul>${resumenGuias}</ul>` : ''}
    <table style="border-collapse:collapse;font-size:13px;">
      <thead><tr style="background:#f4f6fa;">
        <th style="padding:4px 8px;border:1px solid #ddd;">#</th>
        <th style="padding:4px 8px;border:1px solid #ddd;">Arete SINIIGA / RFID</th>
        <th style="padding:4px 8px;border:1px solid #ddd;">Fuego</th>
        <th style="padding:4px 8px;border:1px solid #ddd;">Categoría</th>
        <th style="padding:4px 8px;border:1px solid #ddd;">Guía</th>
      </tr></thead>
      <tbody>${filas}</tbody>
    </table>
    ${d.order_code ? '<p>Si la orden incluye animales de otras empresas, cada empresa recibe su propio correo y su ADMIN autoriza solo su parte.</p>' : ''}
    <p>⚠️ ${total > 1 ? 'Estas solicitudes vencen' : 'Esta solicitud vence'} el ${esc(d.vence_dia_cdmx)} a las 23:59 (hora CDMX) si no se autoriza${total > 1 ? 'n' : ''}. El precio y la forma de pago se capturan al aprobar en el panel.</p>
    <p><a href="${PANEL_URL}" style="background:#2fb344;color:#fff;padding:10px 20px;text-decoration:none;border-radius:4px;">Ir a Autorizaciones Pendientes</a></p>
  `;

  const subject = d.order_code
    ? `[Agro ERP] ${d.order_code} — ${total} animal(es) por autorizar — ${d.company_name}`
    : `[Agro ERP] Autorización pendiente: ${tipoLegible} — ${animales[0]?.rfid_siniiga || animales[0]?.numero_fuego || animales[0]?.electronic_rfid || 'Sin identificador'}`;

  out.push({ json: { request_ids: d.request_ids, to: d.admin_emails, subject, html } });
}
return out;
